export interface Logger {
  log(...args: unknown[]): void;
  error(...args: unknown[]): void;
}
export function useLogger(logger: Logger): string;
export function callFn(fn: (...args: unknown[]) => void): void;
export function isConsole(value: unknown): boolean;
export function describe(value: unknown): string;
export function useUntyped(value: any): boolean;
